window.MG_LAZY_DATA["data/lazy/resources/security-v27-076-72cd89b39ca8a836.json"]={sha256:"72cd89b39ca8a8366a7a3b6099dba1ba76bd68f4fd733b777a675b4a0dfbc64b",value:{"sources":[{"id":"v27-case-7100ed7338e08555","url":"https://docs.velociraptor.app/docs/clients/monitoring/","title":"Velociraptor client monitoring","titleEn":"Velociraptor client monitoring","publisher":"Velociraptor","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v27-076","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v27-076","related":[{"id":"security-v27-077","referenceUrls":["https://www.sleuthkit.org/sleuthkit/man/mactime.html"],"title":"The Sleuth Kit mactime：MACB欄位展開與事件去重邊界","titleEn":"The Sleuth Kit mactime: MACB expansion and event-count boundaries","why":"用兩課的可觀察驗收條件比較模型邊界：交付monitor-version.json、sequence-receipts.csv、missing-ranges.json及retention-model.md；標示模型假設與產品文件的不同層次。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver monitor-version.json, sequence-receipts.csv, missing-ranges.json and retention-model.md. Explicitly distinguish the local teaching assumptions from the product capabilities documented by the source.","difference":"保存檔案身份、來源檔案系統、時間屬性標籤與原始精度；計算時間觀測數，另列同時間的屬性群，不推論未被觀測的操作。","differenceEn":"Preserve file identity, source filesystem, timestamp-attribute labels and original precision. Count timestamp observations, separately group coincident attributes, and avoid inferring operations that the evidence does not directly identify.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["Velociraptor用端點事件查詢執行監測；本課另定每秒固定速率、滿載丟最舊及無壓縮的合成模型，真實保留需查實際設定。 本課所有數值、事件與系統狀態均為原創合成資料；只在本機檔案與授權隔離練習中處理，不接觸生產設備或他人資料。 離線600秒，每秒5筆，共3000序號；緩衝只容2000筆。以事件數而非位元組建模，回連後假設完整送出仍保留的資料。 緩衝保留2000/5=400秒，最初1000筆無法由此緩衝補回；保存比例2000/3000=66.666667%。","mactime將body file的時間資料整理為時間線；MACB代表不同時間屬性，具體語意隨檔案系統而異，相同時間不必然相同事件。 本課所有數值、事件與系統狀態均為原創合成資料；只在本機檔案與授權隔離練習中處理，不接觸生產設備或他人資料。 10個合成檔案，各有4個已知時間欄位，共40觀測；其中6檔四欄相同，其餘4檔四欄皆不同。群鍵為檔案ID加時間值。 按檔案與時間群組得到6×1+4×4=22群；40/22=1.818182只是觀測對群比例，不是動作去重的真實倍率。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Velociraptor supports endpoint monitoring through event queries. This fixture separately assumes fixed event rate, oldest-first eviction and no compression; actual retention must be established from the deployed configuration. Every quantity, event and system state below is original synthetic teaching data. Work only on local files or an explicitly authorized isolated lab, without production access or other people’s data. The endpoint is offline for 600 seconds at five events per second, producing 3,000 sequence numbers. Capacity is 2,000 records, measured in events rather than bytes; all retained records are delivered after reconnection. The buffer retains 2,000/5=400 seconds. Its earliest 1,000 records cannot be recovered from this buffer; the retained fraction is 2,000/3,000=66.666667%.","mactime organizes temporal fields from a body file into a timeline. MACB denotes different timestamp attributes whose exact meaning depends on the filesystem; equal timestamps need not imply one shared underlying operation. Every quantity, event and system state below is original synthetic teaching data. Work only on local files or an explicitly authorized isolated lab, without production access or other people’s data. Ten synthetic files each have four known time attributes, totaling forty observations. Six files have four equal values; four have four distinct values. Group by file identity and timestamp value. Grouping by file and timestamp produces 6×1+4×4=22 groups. The 40/22=1.818182 ratio compares observations to groups; it is not a verified deduplication factor for user actions.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v27-086","referenceUrls":["https://restic.readthedocs.io/en/stable/060_forget.html"],"title":"restic：快照可達集合、共享區塊與清理的安全邊界","titleEn":"restic: snapshot reachability, shared chunks and cleanup boundaries","why":"用兩課的可觀察驗收條件比較模型邊界：交付monitor-version.json、sequence-receipts.csv、missing-ranges.json及retention-model.md；標示模型假設與產品文件的不同層次。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver monitor-version.json, sequence-receipts.csv, missing-ranges.json and retention-model.md. Explicitly distinguish the local teaching assumptions from the product capabilities documented by the source.","difference":"建立快照到內容區塊的引用圖，計算保留快照可達聯集及不可達區塊；只輸出模擬清理計畫，不執行真實forget或prune。","differenceEn":"Build a snapshot-to-content reference graph and calculate the union reachable from retained snapshots plus unreachable chunks. Produce only a simulated cleanup plan, without running real forget or prune commands.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["Velociraptor用端點事件查詢執行監測；本課另定每秒固定速率、滿載丟最舊及無壓縮的合成模型，真實保留需查實際設定。 本課所有數值、事件與系統狀態均為原創合成資料；只在本機檔案與授權隔離練習中處理，不接觸生產設備或他人資料。 離線600秒，每秒5筆，共3000序號；緩衝只容2000筆。以事件數而非位元組建模，回連後假設完整送出仍保留的資料。 緩衝保留2000/5=400秒，最初1000筆無法由此緩衝補回；保存比例2000/3000=66.666667%。","restic區分移除快照參照與清理不再需要的資料；本課以每區塊1MB且無封裝額外成本建模，實際釋放空間還受pack與重打包影響。 本課所有數值、事件與系統狀態均為原創合成資料；只在本機檔案與授權隔離練習中處理，不接觸生產設備或他人資料。 S1引用a,b,c,d；S2引用c,d,e；S3引用d,e,f。全庫6個區塊，保留S2與S3，移除S1的引用。 保留聯集c,d,e,f共4MB，不可達a,b共2MB；S1的4MB不能全部清理，因c,d仍共享。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Velociraptor supports endpoint monitoring through event queries. This fixture separately assumes fixed event rate, oldest-first eviction and no compression; actual retention must be established from the deployed configuration. Every quantity, event and system state below is original synthetic teaching data. Work only on local files or an explicitly authorized isolated lab, without production access or other people’s data. The endpoint is offline for 600 seconds at five events per second, producing 3,000 sequence numbers. Capacity is 2,000 records, measured in events rather than bytes; all retained records are delivered after reconnection. The buffer retains 2,000/5=400 seconds. Its earliest 1,000 records cannot be recovered from this buffer; the retained fraction is 2,000/3,000=66.666667%.","restic separates removing snapshot references from pruning unneeded data. The model gives each chunk one MB with no packaging overhead; actual reclaimed space also depends on packs and repacking behavior. Every quantity, event and system state below is original synthetic teaching data. Work only on local files or an explicitly authorized isolated lab, without production access or other people’s data. S1 references a,b,c,d; S2 references c,d,e; S3 references d,e,f. The repository has six chunks. Retain S2 and S3 while removing only the S1 snapshot reference. The retained union c,d,e,f totals four MB; unreachable a,b total two MB. S1 four-MB content cannot all be reclaimed because c and d remain shared by retained snapshots.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v27-case-963d63c47bd2a97d","url":"https://www.sleuthkit.org/sleuthkit/man/mactime.html","title":"The Sleuth Kit: mactime","titleEn":"The Sleuth Kit: mactime","publisher":"The Sleuth Kit","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v27-case-fefc3bf02d30922f","url":"https://restic.readthedocs.io/en/stable/060_forget.html","title":"restic removing snapshots and pruning","titleEn":"restic removing snapshots and pruning","publisher":"restic","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
